files.test_tasks.py:
import unittest
from screen import view
class Tests(unittest.TestCase):
    def test_open_view(self):
        rows = [{'title': 'a', 'done': False}, {'title': 'b', 'done': True}]
        self.assertEqual(view(rows), {'rows': [rows[0]], 'count': 1})
    def test_empty(self): self.assertEqual(view([]), {'rows': [], 'count': 0})

